const raiz = process.cwd();
const salir = (m) => { console.error('\nERROR: ' + m); process.exit(1); };
const avisos = [];
if (!fs.existsSync(path.join(raiz, 'web', 'src', 'features', 'modulos.js'))) salir('Primero aplica paso0.mjs (no existe web/src/features/modulos.js).');
if (!process.argv.includes('--forzar')) {
  try {
    if (execSync('git status --porcelain', { cwd: raiz }).toString().trim()) salir('Hay cambios sin commit. Haz commit (o stash) antes, o usa --forzar.');
  } catch { salir('No se pudo leer el estado de Git. Usa --forzar si no usas Git.'); }
}
const existe = (r) => fs.existsSync(path.join(raiz, r));
const leer = (r) => fs.readFileSync(path.join(raiz, r), 'utf8').replace(/\r\n/g, '\n');
const salida = new Map();

for (const [rel, cambios] of Object.entries(ESTRICTOS)) {
  let t = leer(rel);
  for (const [ancla, nuevo] of cambios) {
    if (t.includes(nuevo)) continue; // ya aplicado
    const n = t.split(ancla).length - 1;
    if (n !== 1) salir(`En ${rel} no se encontró (o está repetido) este texto:\n${ancla}\nNo se modificó nada.`);
    t = t.replace(ancla, () => nuevo);
  }
  salida.set(rel, t);
}
for (const [rel, cambios] of Object.entries(SUAVES)) {
  if (!existe(rel)) { avisos.push(`No existe ${rel}; omitido.`); continue; }
  let t = leer(rel);
  for (const [ancla, nuevo] of cambios) {
    if (t.includes(nuevo)) continue;
    if (t.split(ancla).length - 1 !== 1) { avisos.push(`En ${rel} no se encontró un punto de inserción (¿falta pegar la trazabilidad?). Omitido: ${ancla.split('\n')[0].trim()}`); continue; }
    t = t.replace(ancla, () => nuevo);
  }
  salida.set(rel, t);
}
for (const [rel, [marca, texto]] of Object.entries(AGREGAR)) {
  if (!existe(rel)) { avisos.push(`No existe ${rel}; omitido.`); continue; }
  const t = leer(rel);
  salida.set(rel, t.includes(marca) ? t : t.replace(/\s*$/, '\n') + texto);
}
for (const [rel, contenido] of Object.entries(NUEVOS)) {
  if (existe(rel)) { avisos.push(`Ya existe ${rel}; se omite.`); continue; }
  salida.set(rel, contenido);
}
for (const [rel, [nuevo, anterior]] of Object.entries(REEMPLAZOS)) {
  if (!existe(rel)) { salida.set(rel, nuevo); continue; }
  const actual = leer(rel);
  if (actual === nuevo) continue;
  if (actual.trim() === anterior.trim()) salida.set(rel, nuevo);
  else { salida.set(rel + '.fase1', nuevo); avisos.push(`${rel} tiene cambios tuyos; la versión nueva quedó en ${rel}.fase1 para que la combines.`); }
}
for (const [rel, contenido] of salida) {
  fs.mkdirSync(path.dirname(path.join(raiz, rel)), { recursive: true });
  fs.writeFileSync(path.join(raiz, rel), contenido, 'utf8');
  console.log('  Escrito: ' + rel);
}
avisos.forEach((a) => console.log('  AVISO: ' + a));
console.log(`\nListo: ${salida.size} archivos. Siguiente: cd web && npm test && npm run dev:mock`);
console.log('Luego ejecuta supabase/migrations/20261028100000_fase1_cliente_membresias_checkin.sql en el SQL Editor de Supabase.');
